// Read cached dashboard data from Static Data
const staticData = $getWorkflowStaticData('global');
const cached = staticData.todayNutrition;

if (!cached) {
  return [{ json: { error: 'no_data_yet', message: 'Кэш ещё не сформирован. Подождите несколько минут.' } }];
}

// Add computed_at to the response
const response = { ...cached };
response.computed_at = staticData.computedAt;
return [{ json: response }];

// 1. Получаем все данные из предыдущей ноды (Google Sheets — Meals)
const allMeals = $input.all();

// 2. Формируем сегодняшнюю дату в формате 'YYYY-MM-DD' для поиска
// $today доступен в объекте $env, но надежнее использовать объект DateTime
const todayStr = $now.toFormat('yyyy-MM-dd');

// 3. Фильтруем массив: оставляем только те записи, где дата начинается с todayStr
const todayMeals = allMeals.filter(item => {
  // Проверяем, существует ли поле Date и является ли оно строкой
  if (item.json.Date && typeof item.json.Date === 'string') {
    return item.json.Date.startsWith(todayStr);
  }
  return false;
});

// 4. (Опционально) Получаем данные профиля, если они вам нужны
// Обратите внимание на точное совпадение имени ноды Profile!
// const profileData = $('Google Sheets — Profile').first().json;

// Возвращаем отфильтрованные данные дальше по цепочке
return todayMeals;

// 1. Профиль (обращаемся по имени ноды)
const profileRows = $('Get Nutrition-Profile').all();
const profile = profileRows.length > 0 ? profileRows[0].json : {};

// 2. Приёмы пищи за сегодня (нода фильтрации по её точному имени)
const mealsData = $('Code in JavaScript').all();

// health.meals — колонки TEXT (Postgres), не число: без numToSum строка
// конкатенируется вместо сложения, а .toFixed() на строке кидает TypeError
// (наступили на это 2026-09-16 — Get Nutrition-Meals мигрирован на Postgres
// раньше, эта нода не была обновлена вместе с ним, per-meal вывод ниже уже
// был исправлен корректно, а этот аккумулятор — пропущен).
function numToSum(v) {
  if (v === undefined || v === null || v === '') return 0;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

let totalCalories = 0, totalProteins = 0, totalFats = 0, totalCarbs = 0;
for (const meal of mealsData) {
  totalCalories += numToSum(meal.json.Calories);
  totalProteins += numToSum(meal.json.Proteins);
  totalFats += numToSum(meal.json.Fats);
  totalCarbs += numToSum(meal.json.Carbs);
}

const remainingCalories = (profile.Calories_target || 0) - totalCalories;
const remainingProteins = (profile.Protein_target || 0) - totalProteins;
const remainingFats = (profile.Fat_target || 0) - totalFats;
const remainingCarbs = (profile.Carbs_target || 0) - totalCarbs;

// 3. Числовой парсер: в Daily_Trends значения хранятся как строки с запятой ("24,3"), не точкой
function toNum(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? null : n;
}

// 4. Последний доступный отчёт из Anomalies_Log (обращаемся по имени — она больше не прямой вход)
// ВАЖНО: поле date в Anomalies_Log — дата АНАЛИЗИРУЕМОГО дня (вчера), не дата генерации.
// Поэтому берём не "сегодня", а самую свежую запись — актуальную до следующего расчёта.
const today = $now.toFormat('yyyy-MM-dd');
const anomaliesRows = $('Get Anomalies-Log').all();
const sortedAnomalies = [...anomaliesRows].sort((a, b) =>
  (a.json.date < b.json.date) ? 1 : (a.json.date > b.json.date ? -1 : 0)
);
const latestAnomalyRow = sortedAnomalies[0];

let anomalies = { count: 0, strong_count: 0, report_date: null, raw: [] };

if (latestAnomalyRow) {
  let rawList = [];
  try {
    rawList = JSON.parse(latestAnomalyRow.json.raw_anomalies || '[]');
  } catch (e) {
    rawList = [];
  }

  // 5. История за 7 дней из Daily_Trends (прямой вход этой ноды — $input)
  // Wellness-домен использует 'Дата' (кириллица) как ключ даты — см. известные особенности проекта.
  const trendsRows = $input.all()
    .map(r => r.json)
    .filter(r => r['Дата'])
    .sort((a, b) => (a['Дата'] < b['Дата']) ? 1 : (a['Дата'] > b['Дата']) ? -1 : 0)
    .slice(0, 7)
    .reverse(); // от старых к новым — так график рисуется слева направо

  // 6. Для каждой аномалии подтягиваем историю значений именно этой колонки
  rawList = rawList.map(a => {
    const history = trendsRows
      .map(row => toNum(row[a.metric]))
      .filter(v => v !== null);
    return { ...a, history };
  });

  anomalies = {
    count: Number(latestAnomalyRow.json.anomaly_count) || 0,
    strong_count: Number(latestAnomalyRow.json.strong_count) || 0,
    report_date: latestAnomalyRow.json.date || null,
    raw: rawList
  };
}

// 7. Итоговый JSON
const finalResult = {
  date: today,
  user: profile.Name || "Неизвестный",
  summary: {
    calories: {
      consumed: totalCalories,
      target: profile.Calories_target || 0,
      remaining: remainingCalories
    },
    macros: {
      proteins: { consumed: totalProteins, target: profile.Protein_target || 0, remaining: remainingProteins },
      fats: { consumed: parseFloat(totalFats.toFixed(1)), target: profile.Fat_target || 0, remaining: parseFloat(remainingFats.toFixed(1)) },
      carbs: { consumed: parseFloat(totalCarbs.toFixed(1)), target: profile.Carbs_target || 0, remaining: parseFloat(remainingCarbs.toFixed(1)) }
    }
  },
  meals_count: mealsData.length,
  meals: mealsData.map(m => ({
    t: String(m.json.Date || '').replace('T', ' ').slice(11, 16),
    d: String(m.json.Meal_description || '').trim(),
    k: Math.round(Number(m.json.Calories) || 0),
    p: Math.round(Number(m.json.Proteins) || 0),
    f: Math.round(Number(m.json.Fats) || 0),
    c: Math.round(Number(m.json.Carbs) || 0),
  })).sort((a, b) => a.t.localeCompare(b.t)),
  anomalies: anomalies
};

return [ { json: finalResult } ];

// Write computed dashboard data to Static Data
const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
staticData.todayNutrition = data;
staticData.computedAt = new Date().toISOString();
return [{ json: { success: true, computedAt: staticData.computedAt } }];

